// Источник: web-теста нет (➕ для приложения). Основание — вердикт 07.10 по тикету #6a86f7d99a8f (עבר QA → הושלם) и бриф .qa/research/6a86f7d99a8f.md
// (реджект 27.09 п.2, 5, 6 исправлены 28.09; переключатель פרקי אבות сделан к 07.10). Опора: S-24 AC5/AC6, реджект 27.09, Figma 632:1447.
// Строки тем (כל הנושאים…) НЕ проверяем — их нет в документации (только в макете), вердикт 07.10.
import { $, driver, expect } from '@wdio/globals';
import { byText, byTextContains, tapText, expectVisibleText, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

// «שיר המעלות» — ровно 15 פרקים: ק״כ–קל״ד (включая קכ״א «שיר למעלות»).
const SHIR_HAMAALOT = ['ק״כ', 'קכ״א', 'קכ״ב', 'קכ״ג', 'קכ״ד', 'קכ״ה', 'קכ״ו', 'קכ״ז', 'קכ״ח', 'קכ״ט', 'ק״ל', 'קל״א', 'קל״ב', 'קל״ג', 'קל״ד'];

function searchField() {
  return driver.isAndroid
    ? $('android=new UiSelector().className("android.widget.EditText")')
    : $('-ios class chain:**/XCUIElementTypeTextField');
}
async function search(text: string) {
  const f = await searchField();
  await f.waitForDisplayed();
  await f.clearValue();
  await f.setValue(text);
}

describe('Список תהילים', () => {
  afterEach(async () => {
    const f = await searchField();
    if (await f.isDisplayed().catch(() => false)) await f.clearValue();
    await toHome();
  });

  it('TH-02 Переключатель «תהילים / פרקי אבות», фильтр дней, поиск по словам, «שיר המעלות» = 15 #6a86f7d99a8f @prod-safe', async () => {
    await goTab('תהילים');
    await (await searchField()).waitForDisplayed({ timeout: 20000 });

    // 1. Переключатель «תהילים / פרקי אבות»: переход в פרקי אבות убирает список תהילים, возврат — список на месте.
    await expectVisibleText('פרקי אבות');
    await tapText('פרקי אבות');
    await expect(byTextContains('אשרי האיש')).not.toBeDisplayed();
    await tapText('תהילים');
    await expect(byTextContains('אשרי האיש')).toBeDisplayed();

    // 2. Фильтр дней (принятое деление: א׳ 1–29 … שבת 120–150).
    await expectVisibleText('כל הימים');
    await tapText('שבת');
    await expect(byTextContains('שיר המעלות')).toBeDisplayed();     // первый в שבת — ק״כ
    await expect(byTextContains('אשרי האיש')).not.toBeDisplayed();  // פרק א׳ — не в שבת
    await tapText('א׳');
    await expect(byTextContains('אשרי האיש')).toBeDisplayed();
    await tapText('כל הימים');
    await expect(byTextContains('אשרי האיש')).toBeDisplayed();

    // 3. Поиск слов по всему פרק без учёта ניקוד (реджект 27.09 п.5): «רעי לא אחסר» → כ״ג; открытие ведёт к этому פרק (S-24 AC6).
    await search('רעי לא אחסר');
    await expect(byTextContains('לא נמצאו פרקים')).not.toBeDisplayed();
    await (await byTextContains('כ״ג')).click();
    await expectVisibleText('תהילים כ״ג');
    await driver.back();
    await (await searchField()).waitForDisplayed();

    // 4. «שיר המעלות» → все 15 (ק״כ–קל״ד), включая קכ״א; соседей קי״ט и קל״ה нет (реджект 27.09 п.6).
    await search('שיר המעלות');
    for (const n of SHIR_HAMAALOT) await scrollToText(n, 12);
    await expect(byTextContains('קי״ט')).not.toBeDisplayed();
    await expect(byTextContains('קל״ה')).not.toBeDisplayed();

    // 5. Нет результатов → сообщение + «ניקוי החיפוש».
    await search('QA-AUTO-אין-כזה');
    await expectTextContains('לא נמצאו פרקים');
    await tapText('ניקוי החיפוש');
    await expect(byText('ניקוי החיפוש')).not.toBeDisplayed();
  });
});
